<template>
    <iframe v-if="appPlugin.app"
        ref="iframeRef"
        :src="appPlugin.app?.url"
        sandbox="allow-scripts allow-same-origin allow-modals"
        allow="autoplay; camera; midi; fullscreen " 
        contain="strict"
    ></iframe>
        <!-- @load="ready" -->
</template>

<script setup>
    import { ref, watch, onMounted, onBeforeUnmount } from 'vue'

    const appPlugin = stores.appPlugin();
    const modals = stores.modals();
    const user = stores.user();
    const locale = stores.locale();

    const iframeRef = ref(null);

    let pageTitle = document.title;


    // Обработка ответов
        const updateLocale = (payload) => {
            locale.updateLocale(payload.value);
        }

    const ready = () => {
        appPlugin.isIframeReady = true;
        appPlugin.sendInitMessage();

        setTimeout(() => {
            modals.close('loader')
            setTimeout(() => {
                document.documentElement.style.overflow = 'hidden';
            });
        }, 300);
    }

    const onMessage = (event) => {
        if (!event.data || typeof event.data !== 'object') {
            return;
        }

        const { type, payload } = event.data

        switch (type) {
            case 'CMD_CLOSE':
                appPlugin.clearApp();
                break

            case 'CMD_LOGIN':
                modals.open('auth');
                break

            case 'CMD_ACTIVE_PROFILE':
                appPlugin.setActiveProfile(payload);
                break

            case 'CMD_LOCALE':
                locale.updateLocale(payload);
                break

            case 'APP_API_READY':
                ready();
                break;
                
        }
    }

    onMounted(() => {
        modals.open('loader', {
            data: {
                name: 'Miracle'
            }
        });

        window.addEventListener('message', onMessage);

        appPlugin.isIframeReady = false;
        appPlugin.setFrame(iframeRef);

        if (appPlugin.app?.name) {
            document.title = `${ appPlugin.app.name } | ${ pageTitle }`
        }
    });

    onBeforeUnmount(() => {
        document.title = pageTitle;
        document.documentElement.style.overflow = '';
        appPlugin.isIframeReady = false;

        window.removeEventListener('message', onMessage)
    });
</script>

<style scoped>
    iframe {
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        height: 100vh;
        width: 100%;
        border: none;
        contain: strict;
        pointer-events: none;
        background: rgba(12, 13, 14, 0.95);
        pointer-events: auto;
        z-index: 999;
    }
</style>
